The staking-indexer is responsible for checking every transaction happening on the BTC network in order to recognize once a valid staking, unbonding or withdrawal transaction adhering to Babylon's standards is committed to BTC. For every kind of the above mentioned transactions, a different action is performed. In every case system metrics are recorded and the system state is reported and updated accordingly. Now withdrawal can be separated into two separate types based on the following:
• Spends a staking transaction.
• Spends a unbonding transaction.
This particular issue appears in a third case when a user spends an unbonding and a staking transaction within one transaction. In bitcoin a transaction is basically an object that has inputs and outputs, where inputs deﬁne where the funds for one or more outputs should come from. Outputs deﬁne under which circumstances these funds can then be spent. These outputs can then be used as inputs for new transactions so funds just "travel" from transaction to transaction. Now a transaction can have more than one input and more than one outputs. Babylon deﬁnes the above mentioned special transactions here. Important to note here is that the Timelock path can be spent once the timelock expires. Additionally, withdrawal transactions are not deﬁned and therefore have no restrictions as none can be enforced as once the timelock expires, the user can withdraw just with their own signature, not needing additional signatures as in the other paths. This means that withdrawal transactions are not restricted to having a limited amount of in-/outputs. Looking at HandleConfirmedBlock in staking-indexer/indexer/indexer.go, this is how the indexer checks whether it is indexing a withdrawal transaction of a staking OR unbonding transaction:
```go
func (si *StakingIndexer) HandleConfirmedBlock(b *types.IndexedBlock) error {
    params, err := si.paramsVersions.GetParamsForBTCHeight(b.Height)
    if err != nil {
        return err
    }
    for _, tx := range b.Txs {
        msgTx := tx.MsgTx()
        // [...]
        // 2. not a staking tx, check whether it is a spending tx from a previous
        // staking tx, and handle it if so
        stakingTx, spendingInputIdx := si.getSpentStakingTx(msgTx)
        if spendingInputIdx >= 0 {
            // this is a spending tx from a previous staking tx, further process it
            // by checking whether it is unbonding or withdrawal
            if err := si.handleSpendingStakingTransaction(
                msgTx, stakingTx, spendingInputIdx,
                uint64(b.Height), b.Header.Timestamp); err != nil {
                return err
            }
            continue // [1]
        }
        // 3. it's not a spending tx from a previous staking tx,
        // check whether it spends a previous unbonding tx, and
        // handle it if so
        unbondingTx, spendingInputIdx := si.getSpentUnbondingTx(msgTx)
        if spendingInputIdx >= 0 {
            // this is a spending tx from the unbonding, validate it, and processes it
            if err := si.handleSpendingUnbondingTransaction(
                msgTx, unbondingTx, spendingInputIdx, uint64(b.Height)); err != nil {
                return err
            }
            continue
        }
    }
```
The functions getSpentStakingTx and getSpentUnbondingTx handle the case where the transaction spends a staking or unbonding transaction respectively. Now note the continue at [1]. This means that if the indexer ﬁnds that the currently parsed transaction has an input that spends a staking transaction, it will not check whether the same transaction also spends an unbonding transaction. Impact: Explanation For the following let's assume the following:
• a user stakes two times
• the user unbonds one of these transactions
• both timelocks expire
• the user withdraws both transactions with one single transaction
Now let's look at this function which is important for the impact:
```go
func (si *StakingIndexer) processWithdrawTx(tx *wire.MsgTx, stakingTxHash *chainhash.Hash, unbondingTxHash
    *chainhash.Hash, height uint64) error {
    txHashHex := tx.TxHash().String()
    if unbondingTxHash == nil {
        si.logger.Info("found a withdraw tx from staking",
            zap.String("tx_hash", txHashHex),
            zap.String("staking_tx_hash", stakingTxHash.String()),
        )
    } else {
        si.logger.Info("found a withdraw tx from unbonding",
            zap.String("tx_hash", txHashHex),
            zap.String("staking_tx_hash", stakingTxHash.String()),
            zap.String("unbonding_tx_hash", unbondingTxHash.String()),
        )
    }
    withdrawEvent := queuecli.NewWithdrawStakingEvent(stakingTxHash.String())
    if err := si.consumer.PushWithdrawEvent(&withdrawEvent); err != nil {
        return fmt.Errorf("failed to push the withdraw event to the consumer: %w", err)
    }
    // record metrics
    if unbondingTxHash == nil {
        totalWithdrawTxsFromStaking.Inc()
        lastFoundWithdrawTxFromStakingHeight.Set(float64(height))
    } else {
        totalWithdrawTxsFromUnbonding.Inc()
        lastFoundWithdrawTxFromUnbondingHeight.Set(float64(height))
    }
    return nil
}
```
This is called in handleSpendingUnbondingTransaction and handleSpendingStakingTransaction. Here the system updates metrics and pushes a WithdrawEvent. This event then gets consumed by the staking-api-service in the function WithdrawStakingHandler in staking-api-service/internal/queue/handlers/withdraw.go:
```go
func (h *QueueHandler) WithdrawStakingHandler(ctx context.Context, messageBody string) *types.Error {
    var withdrawnStakingEvent queueClient.WithdrawStakingEvent
    err := json.Unmarshal([]byte(messageBody), &withdrawnStakingEvent)
    if err != nil {
        log.Ctx(ctx).Error().Err(err).Msg("Failed to unmarshal the message body into withdrawnStakingEvent")
        return types.NewError(http.StatusBadRequest, types.BadRequest, err)
    }
    // [...]
    // Transition to withdrawn state
    // Please refer to the README.md for the details on the event processing workflow
    transitionErr := h.Services.TransitionToWithdrawnState(
        ctx, withdrawnStakingEvent.StakingTxHashHex,
    )
    if transitionErr != nil {
        return transitionErr
    }
    return nil
}
```
Here the transaction's state is set to withdrawn in the database. Since the transactions that is processed has two inputs (one spending the unbonding and one spending the staking transaction), only handleSpendingStakingTransaction is called. This means that the status of the previous staking transaction is properly updated. But handleSpendingUnbondingTransaction is never called due to the continue call at [1] therefore the status of the previous unbonding transaction is never updated to withdrawn even though it has been. Looking at this, the impact of this ﬁnding is an outdated system state, as some transactions will never be marked as withdrawn which is at least a low impact. Likelihood: The likelihood of this happening is HIGH for the following reasons:
1. Any user can trigger this once they staked two times and unbonded one transaction.
2. Users are even incentivized to group multiple withdrawals into one transaction as it costs less fees.

One of the staking-api-service's responsiblities lies in receiving and handling unbonding requests via the api. Any user may send such a request if they want to unbond a previously submitted staking transaction. In order to do so, they must send a request to the endpoint /v1/unbonding. Such requests are checked to be valid unbonding requests and are then added to the Unbonding Requests DB. The key for a transaction is the transaction's hash which is required to be unique in the database. The requests from that database are later taken by the unbonding-pipeline to be signed by the covenant-signers and submitted to bitcoin. By using this API endpoint, users can request unbonding of their staking transactions. The problem is that currently this unbondingTxHash is user provided and not checked in any way. The only sanity check done on it, is if it conforms to being in the format of a bitcoin transaction hash. Due to this, any user can provide any unbondingTxHash they want and no other user can add another element with that same key as all keys must be unique due to this check:

```solidity
func (s *Services) UnbondDelegation(ctx context.Context, stakingTxHashHex, unbondingTxHashHex, txHex, signatureHex string) *types.Error {
    // [...]
    // 3. save unbonding tx into DB
    err = s.DbClient.SaveUnbondingTx(ctx, stakingTxHashHex, unbondingTxHashHex, txHex, signatureHex)
    if err != nil {
        if ok := db.IsDuplicateKeyError(err); ok { // <-----
            log.Ctx(ctx).Warn().Err(err).Msg("unbonding request already been submitted into the system")
            return types.NewError(http.StatusForbidden, types.Forbidden, err)
        } else if ok := db.IsNotFoundError(err); ok {
            log.Ctx(ctx).Warn().Err(err).Msg("no active delegation found for unbonding request")
            return types.NewError(http.StatusForbidden, types.Forbidden, err)
        }
        log.Ctx(ctx).Error().Err(err).Msg("failed to save unbonding tx")
        return types.NewError(http.StatusInternalServerError, types.InternalServiceError, err)
    }
    return nil
}

func (db *Database) SaveUnbondingTx(
    ctx context.Context, stakingTxHashHex, txHashHex, txHex, signatureHex string,
) error {
    delegationClient := db.Client.Database(db.DbName).Collection(model.DelegationCollection)
    unbondingClient := db.Client.Database(db.DbName).Collection(model.UnbondingCollection)
    // Start a session
    session, err := db.Client.StartSession()
    if err != nil {
        return err
    }
    defer session.EndSession(ctx)
    // Define the work to be done in the transaction
    transactionWork := func(sessCtx mongo.SessionContext) (interface{}, error) {
        // [...]
        _, err = unbondingClient.InsertOne(sessCtx, unbondingDocument)
        if err != nil {
            var writeErr mongo.WriteException
            if errors.As(err, &writeErr) {
                for _, e := range writeErr.WriteErrors {
                    if mongo.IsDuplicateKeyError(e) {
                        return nil, &DuplicateKeyError{ // <-----
                            Key: txHashHex,
                            Message: "unbonding transaction already exists",
                        }
                    }
                }
            }
            return nil, err
        }
        return nil, nil
    }
}
