The function executePayroll() executes multiple transactions in one go, but it can be frontrun to execute a subset of the transactions. Note this requires careful crafting of the parameters. This splitting leads to several problems:
• the retrieval from the allowance contract (execTransactionFromGnosis()) can be split into a large number of small transactions. This uses up the nonces in the allowance contract. As these nonces are limited to a maximum of 65535 this would finally prevent further payments;
• if a subset is executed (successfully) before the original transaction, then the original transaction will fail and has to be rescheduled (minus the succeeded transaction). This requires gas, effort, and time;
• if the original transaction is delayed multiple times, then the allowance time period (e.g. a month) could be passed and the allowance for that period would be forfeited (lost). This could require coordination efforts to fix.
function executePayroll(...) ... {
    ...
    for (uint256 index = 0; index < paymentTokens.length; index++) {
        execTransactionFromGnosis(...);
    }
    ...
}
contract AllowanceModule is ... {
    struct Allowance {
        uint96 amount;
        uint96 spent;
        uint16 resetTimeMin;
        uint32 lastResetMin;
        uint16 nonce; // 16 bits so max 65535
    }
}

The function offboard() deletes orgs[msg.sender], which also deletes packedPayoutNonces[].
If the same safe would ever onboard(), with (more or less) the same approvers, then all previous transactions could be re-executed because all the nonces are reset. This could drain the safe.
struct ORG {
    uint128 approverCount;
    uint128 approvalsRequired;
    mapping(address => address) approvers;
    uint256[] packedPayoutNonces;
}
mapping(address => ORG) public orgs;
function offboard() external {
    ...
    delete orgs[msg.sender]; // also deletes packedPayoutNonces
    ...
}

Throughout the codebase, there are calls to multiple policy contracts, and the ValidationData return values from these calls are intended to be combined using the intersectValidationData() function. However, there are currently two locations in the codebase where the intersectValidationData() function is not properly called, and previous ValidationData results are overwritten instead of combined. These two locations are: 1. In PolicyLib.sol, the check() function combines each policy's return value with itself instead of accumulating across the entire loop:
```solidity
function check(/* ... */ ) internal returns (ValidationData vd) {
    // ....
    for (uint256 i; i < length; i++) {
        // ...
        uint256 validationDataFromPolicy = uint256(bytes32(policies[i].safeCall({ callData: callOnIPolicy })));
        vd = ValidationData.wrap(validationDataFromPolicy);
        // ...
        if (vd.isFailed()) revert ISmartSession.PolicyViolation(permissionId, policies[i]);
        // ...
        vd = vd.intersectValidationData(vd);
    }
}
```
2. In SmartSession.sol, the _enforcePolicies() function overwrites the userOp policy return value with the action policy return value:
```solidity
function _enforcePolicies(/* ... */ ) internal returns (ValidationData vd) {
    // ...
    vd = $userOpPolicies.check({/* ... */ });
    // ...
    if (selector == IERC7579Account.execute.selector) {
        // ...
    } else if (callType == CALLTYPE_BATCH) {
        vd = $actionPolicies.actionPolicies.checkBatch7579Exec({/* ... */});
    }
    // DEFAULT EXEC & SINGLE CALL
    else if (callType == CALLTYPE_SINGLE) {
        // ...
        vd = $actionPolicies.actionPolicies.checkSingle7579Exec({/* ... */});
    }
    // ...
    else {
        // ...
        vd = $actionPolicies.actionPolicies[actionId].check({/* ... */});
    }
    // ...
}
```
The consequences of this issue are partially mitigated by the isFailed() check, as this helper function reverts if any individual policy fails. However, unexpected behavior could arise if intersectValidationData() returns an intermediate error, or if a policy returns a validAfter or validUntil timestamp, since these values will sometimes be overwritten.

In two different parts of the codebase, an array is iterated over while its elements are simultaneously removed. Because each removal will shift the indices of the remaining elements, both locations of this behavior will fail to remove all elements that are intended to be removed.
For example, consider the _removeAll() function:
```solidity
function _removeAll(Set storage set, address account) internal {
    uint256 len = _length(set, account);
    for (uint256 i; i < len; i++) {
        _remove(set, account, _at(set, account, i));
    }
}
```
Since each call to _remove() will decrease the length of the set and will shuffle the elements inside of it, the second half of this loop will attempt to remove elements at indices that no longer exist.
The other location of this problem is in the onUninstall() function, which has the below implementation:
```solidity
function onUninstall(bytes calldata /*data*/ ) external override {
    uint256 configIdsCnt = $enabledSessions.length({ account: msg.sender });
    for (uint256 i; i < configIdsCnt; i++) {
        PermissionId configId = PermissionId.wrap($enabledSessions.at({ account: msg.sender, index: i }));
        removeSession(configId);
    }
}
```
In both cases, arrays are not fully cleared as expected, leaving permissions and other associated values active in storage despite the intent to remove them.

In the current implementation of the tryCheck() function, if the minimum policy threshold (minPolicies) is not met, the function returns RETRY_WITH_FALLBACK to indicate that the system should re-attempt the action policy check using the FALLBACK_ACTIONID. This can be seen in the following code snippets:
```solidity
function tryCheck(/* ... */ ) /* ... */ {
    // ...
    if (minPolicies > length) {
        return RETRY_WITH_FALLBACK;
    }
    // ...
}
```
```solidity
function checkSingle7579Exec(/* ... */ ) /* ... */ {
    // ...
    vd = $policies[actionId].tryCheck({/* ... */});
    // ...
    if (vd == RETRY_WITH_FALLBACK) {
        // If no policies were configured for FALLBACK_ACTIONID for this PermissionId, this will revert
        vd = $policies[FALLBACK_ACTIONID].check({/* ... */});
    }
    return vd;
}
```
This fallback behavior is not properly implemented in the _enforcePolicies() function. More specifically, when native account function calls are being verified, the tryCheck() function is used but the return value is passed directly into the intersect() function:
```solidity
vd = vd.intersect(
    $actionPolicies.actionPolicies[actionId].tryCheck({/* ... */})
);
```
As a result, any native account function that does not have an action policy will directly pass RETRY_WITH_FALLBACK into intersect().
Since RETRY_WITH_FALLBACK is defined as ValidationData.wrap(uint256(0x50FFBAAD)), this can lead to unexpected results instead of a failure.

When a user installs a session, several different storage locations are initialized sequentially. For example, consider the enableSessions() implementation below:
```solidity
function enableSessions(Session[] calldata sessions) public returns (PermissionId[] memory permissionIds) {
    uint256 length = sessions.length;
    if (length == 0) revert InvalidData();
    permissionIds = new PermissionId[](length);
    for (uint256 i; i < length; i++) {
        Session calldata session = sessions[i];
        PermissionId permissionId = session.toPermissionId();
        // ...
        $enabledSessions.add({ /* ... */ });
        // ...
        $sessionValidators.enable({/* ... */});
        // ...
        $userOpPolicies.enable({/* ... */});
        // ...
        $erc1271Policies.enable({/* ... */});
        $enabledERC7739Content.enable(/* ... */);
        // ...
        $actionPolicies.enable({/* ... */});
        // ...
    }
}
```
Note that any of these storage initialization steps may result in an external call, which would grant control flow to another contract. One low-risk example is with the external calls to registry.checkForAccount().
A higher-risk example is the initializeWithMultiplexer() function, which is invoked on each installed policy. While these calls are generally trusted (as the user chooses the policies they install), even a non-malicious policy could inadvertently give up control flow to an untrusted contract.
If an attacker does gain control flow during an installation, they could potentially exploit the unfinished installation state. For instance, in the above code, notice that $sessionValidators.enable() happens before $erc1271Policies.enable(). So, if an attacker gains control flow after $sessionValidators.enable() but before $erc1271Policies.enable(), they may be able to successfully call isValidSignature(), bypassing all of the $erc1271Policies that are yet to be installed.

When a policy is disabled in the SmartSession system, there is no logic that is executed to clean up the policy's storage. So, to avoid issues if a policy is re-enabled with the same configId, policies are supposed to clear any existing storage during the initializeWithMultiplexer() call. This is explained in the following comment from the code:
```solidity
/**
 * Disables specified policies for a given permission ID and smart account.
 *
 * @dev This function removes the specified policies from the policy list and emits events for each disabled policy.
 * @notice Cleaning state on policies is not required as on enable, initializeWithMultiplexer is called which MUST
 * overwrite the current state.
...
 */
```
However, in the ERC20SpendingLimitPolicy, the initializeWithMultiplexer() function does not fully implement this overwriting. The function is currently implemented as follows:
```solidity
function initializeWithMultiplexer(address account, ConfigId configId, bytes calldata initData) external {
    (address[] memory tokens, uint256[] memory limits) = abi.decode(initData, (address[], uint256[]));
    for (uint256 i; i < tokens.length; i++) {
        address token = tokens[i];
        uint256 limit = limits[i];
        if (token == address(0)) revert InvalidTokenAddress(token);
        if (limit == 0) revert InvalidLimit(limit);
        TokenPolicyData storage $ = _getPolicy({ id: configId, userOpSender: account, token: token });
        $.spendingLimit = limit;
    }
    emit IPolicy.PolicySet(configId, msg.sender, account);
}
```
This is not fully correct because it does not reset the alreadySpent value in storage. The following modification could address this:
```solidity
function initializeWithMultiplexer(address account, ConfigId configId, bytes calldata initData) external {
    (address[] memory tokens, uint256[] memory limits) = abi.decode(initData, (address[], uint256[]));
    for (uint256 i; i < tokens.length; i++) {
        address token = tokens[i];
        uint256 limit = limits[i];
        if (token == address(0)) revert InvalidTokenAddress(token);
        if (limit == 0) revert InvalidLimit(limit);
        TokenPolicyData storage $ = _getPolicy({ id: configId, userOpSender: account, token: token });
        $.spendingLimit = limit;
        $.alreadySpent = 0;
    }
    emit IPolicy.PolicySet(configId, msg.sender, account);
}
```
However, with this change, there can still be problems if the newest tokens array does not match the tokens array from a previous installation. In this case, the existing tokens array would not have its storage overwritten, which can lead to re-enabling previous storage unintentionally.

Additionally, it can be noted that in most cases the tokens array is not fully necessary. This is because the ERC20SpendingLimitPolicy is an action policy, so the configId passed to initializeWithMultiplexer() will typically commit to a specific target address and function selector. This means there is only one token contract for which the spending limit can actually be reached. The only exception to this is the FALLBACK_ACTIONID, which can potentially reach multiple contracts from the same action policy. Since this one scenario exists where the tokens array can be useful, there can still be issues when the ERC20SpendingLimitPolicy is re-enabled and doesn't clear previous data.

If the provided order to fillLPOrder has a fillAmount == 0, any order will proceed past the following codeblock.
```solidity
bytes32 orderHash = getOrderHash(order);
if (fillAmount > orderHashToRemainingQuantity[orderHash]) revert NotEnoughRemainingQuantity();
orderHashToRemainingQuantity[orderHash] -= fillAmount;
```
If the targetMarketId was never created, the market struct read from storage will take the default value (0).
```solidity
WeirollMarket memory market = marketIDToWeirollMarket[order.targetMarketID];
```
Then, for each order.tokensRequested, the following code block will be entered because market.RewardStyle == 0 == RewardStyle.Upfront.
```solidity
if (market.rewardStyle == RewardStyle.Upfront) {
    if (PointsFactory(POINTS_FACTORY).isPointsProgram(order.tokensRequested[i])) {
        Points(order.tokensRequested[i]).award(order.lp, order.tokenAmountsRequested[i], msg.sender);
    } else {
        //safetransfer the token to the LP
        ERC20(order.tokensRequested[i]).safeTransferFrom(
            msg.sender, order.lp, order.tokenAmountsRequested[i]
        );
    }
}
```
Though this seems to only cause loss of funds for the msg.sender, poorly formed order structs may include market identiﬁers which do not exist inadvertently.

The ERC4626i claimProtocolFees has the following snippet:
```solidity
CampaignData storage _campaignData = campaignIdToData[campaignId];
uint256 lastUpdated = feeRewardsLastClaimed[campaignId];
uint256 elapsed = (_campaignData.end - lastUpdated);
uint256 amountOwed = (elapsed * _campaignData.protocolFeeRate);
```
The ﬁrst time this function is called for a given campaignId, feeRewardsLastClaimed[campaignId] will be 0 (the default value) in storage. This will lead to the time elapsed variable to be assigned to the campaignData.end's timestamp. As a consequence, the amountOwed will be many orders of magnitude larger than the campaign's protocolFeeRate intends. This will impact every campaign created upon the ﬁrst claim.

The VaultOrderbook.allocateOrder() function contains the following logic meant to tally the total reward rate for all tokens in the passed-in campaigns:
```solidity
for (uint256 i = 0; i < campaignIds.length; ++i) {
    // Ensure that the LP could deposit quantity base tokens into the vault and still receive the desired reward rate
    uint256 rate = ERC4626i(order.targetVault).previewRateAfterDeposit(campaignIds[i], quantity);
    tokenToRate[order.tokensRequested[i]] += rate;
}
```
The additive assignment on line 181 (tokenToRate[order.tokensRequested[i]] += rate;) writes to the cache key of tokensRequested[i]; however, the index i is being used to iterate over the campaignIds array. There is no guarantee that the reward token of the campaign id at index i is equal to the requested token at index i, or even that the two arrays are the same length. A malicious caller could exploit this to fool the validation logic into thinking the rate requirements are satisﬁed by passing in campaigns for different tokens than those requested. In particular, since campaign creation is permissionless, a caller could use worthless dummy tokens that they control to create the required campaigns.

The logic in VaultOrderbook.sol#L173-L190 is used in VaultOrderbook.allocateOrder() to check that the reward rates requested in exchange for a deposit can be satisﬁed:
```solidity
for (uint i; i < order.tokenRatesRequested.length; ++i) {
    tokenToRate[order.tokensRequested[i]] = order.tokenRatesRequested[i];
}
// Iterate over each token the LP requested
for (uint256 i = 0; i < campaignIds.length; ++i) {
    // Ensure that the LP could deposit quantity base tokens into the vault and still receive the desired reward rate
    uint256 rate = ERC4626i(order.targetVault).previewRateAfterDeposit(campaignIds[i], quantity);
    tokenToRate[order.tokensRequested[i]] += rate;
}
for (uint i; i < order.tokenRatesRequested.length; ++i) {
    if (order.tokenRatesRequested[i] > tokenToRate[order.tokensRequested[i]]) {
        revert OrderConditionsNotMet();
    }
    delete tokenToRate[order.tokensRequested[i]];
}
```
The ﬁrst loop sets tokenToRate[order.tokensRequested[i]] to be equal to order.tokenRatesRequested[i] for all valid i. The second loop can only increase the value of tokenToRate entries. So in the third loop, the comparison order.tokenRatesRequested[i] > tokenToRate[order.tokensRequested[i]] can never fail and thus the check for rates will always succeed. LPs can have their orders ﬁlled even if they will receive none of the tokens they requested in return.

When a proxy owner uses the execute() function to perform a delegate call, the _safeDelegateCall() function is used:
```solidity
function _safeDelegateCall(address to, bytes memory data) internal returns (bool success, bytes memory response) {
    // Save the owner address in memory so that this variable cannot be modified during the DELEGATECALL.
    address owner_ = owner;
    // Reserve some gas to ensure that the contract call will not run out of gas.
    uint256 stipend = gasleft() - minGasReserve;
    // Delegate call to the provided contract.
    (success, response) = to.delegatecall{ gas: stipend }(data);
    // Check that the owner has not been changed.
    if (owner_ != owner) {
        revert PRBProxy_OwnerChanged(owner_, owner);
    }
}
```
Because the contract that receives the delegate call has the ability to manipulate the storage slots of the proxy, a check is performed at the end to ensure that the owner hasn't changed over the course of the call. However, this check does not ensure that the owner does not change during the call, which could be just as dangerous, allowing a malicious user to temporarily become the owner of the contract for the duration of the call.

The NFT Descriptor contract fetches the symbol from the asset contract using the safeAssetSymbol() function. As long as that symbol has a length of over 64 bytes (ie it is a string), it is returned as is.
```solidity
function safeAssetSymbol(address asset) internal view returns (string memory) {
    (bool success, bytes memory symbol) = asset.staticcall(abi.encodeCall(IERC20Metadata.symbol, ()));
    // Non-empty strings have a length greater than 64, and bytes32 has length 32.
    if (!success || symbol.length <= 64) {
        return "ERC20";
    }
    return abi.decode(symbol, (string));
}
```
This symbol is passed along to the SVG, where it is inserted directly into the SVG text that is returned to the front end to display.
```solidity
function generateFloatingText(
    string memory sablierAddress,
    string memory streamingModel,
    string memory assetAddress,
    string memory assetSymbol
)
    internal
    pure
    returns (string memory)
{
    return string.concat(
        '<text text-rendering="optimizeSpeed">',
        SVGElements.floatingText({
            offset: "-100%",
            text: string.concat(sablierAddress, unicode" • ", "Sablier V2 ", streamingModel)
        }),
        SVGElements.floatingText({
            offset: "0%",
            text: string.concat(sablierAddress, unicode" • ", "Sablier V2 ", streamingModel)
        }),
        SVGElements.floatingText({ offset: "-50%", text: string.concat(assetAddress, unicode" ", assetSymbol) }),
        SVGElements.floatingText({ offset: "50%", text: string.concat(assetAddress, unicode" ", assetSymbol) }),
        "</text>"
    );
}
```
There are no checks on the value of this symbol, and it is passed directly to any front end displaying Sablier NFTs to display. However, SVGs can be used to execute arbitrary Javascript (see: Using-JavaScript-in-SVG and svg-xss-injection-attacks). This means that if an attacker were to create an asset with a symbol that contained malicious Javascript, they could use this to inject Javascript into the Sablier front end. This could be used, for example, to create a fake Metamask pop up that asks a user to sign a message.

The wrapAndCreate functions in the SablierV2ProxyTarget contract allow the user to specify the address of the wrapped native asset (e.g. WETH).
```solidity
function wrapAndCreateWithDurations(
    ISablierV2LockupLinear lockupLinear,
    LockupLinear.CreateWithDurations memory createParams
)
    external
    payable
    override
    onlyDelegateCall
    returns (uint256 streamId)
{
    createParams.totalAmount = uint128(msg.value);
    // Wrap the native asset payment in ERC-20 form.
    IWrappedNativeAsset(address(createParams.asset)).deposit{ value: msg.value }();
    // Approve the Sablier contract to spend funds.
    _approve(address(lockupLinear), createParams.asset, createParams.totalAmount);
    // Create the stream.
    streamId = lockupLinear.createWithDurations(createParams);
}
```
The ETH sent with the transaction is deposited in the contract via the deposit() function. The amount of ETH deposited is msg.value which is used to overwrite the createParams.totalAmount used to create the stream. However, as the WETH address is specified by the user they can choose any other ERC20 contract that can handle a deposit(). If that contract returns less tokens than the ETH deposited this can be used to steal any of those tokens from the proxy. The attack could look like this:
- The returned amount of ERC20 token is less than the msg.value.
- The _approve() then does an infinite approval on the token contract.
- The totalAmount of the stream is set to the msg.value.
- The difference will be taken from the proxy contract's balance when creating the stream.
We haven't found a contract that meets these requirements (although stETH comes close except for the empty calldata check in the fallback function)

As stated in the Uniswap Permit2 documentation here and here, the calling contract should check the intent of the signer on how the signature is used. In SablierV2ProxyTarget, any time funds are transferred the permit2 signature is used to permit the proxy to spend the tokens on behalf of the user.
```solidity
permit2Params.permit2.permit({
    owner: owner_,
    permitSingle: permit2Params.permitSingle,
    signature: permit2Params.signature
});
// Transfer funds from the proxy owner to the proxy.
permit2Params.permit2.transferFrom({ from: owner_, to: address(this), amount: amount, token: address(asset) });
```
This signature however only specifies the proxy address, token contract and token amount; not the target/plugin contract or the function being called, which more precisely covers the intent of the owner when they sign the permit2 allowance.
```solidity
struct PermitSingle {
    // the permit data for a single token allowance
    PermitDetails details;
    // address permissioned on the allowed tokens
    address spender;
    // deadline on the permit signature
    uint256 sigDeadline;
}

struct PermitDetails {
    // ERC20 token address
    address token;
    // the maximum amount allowed to spend
    uint160 amount;
    // timestamp at which a spender's token allowances become invalid
    uint48 expiration;
    // an incrementing value indexed per owner, token, and spender for each signature
    uint48 nonce;
}
```
This means the proxy is able to use the signature to transfer funds from the permit2 contract for any reason. In the event that there is a plugin installed on the proxy that uses permit2, a user can front run the proxy's use of the signature and use the same signature to spend the funds for its own purposes.

There is no sanity check on the input parameter for the new minGasReserve in setMinGasReserve(). The minGasReserve is deducted from the gas stipend to be sent in the delegatecall to a target or plugin contract.
```solidity
function _safeDelegateCall(address to, bytes memory data) internal returns (bool success, bytes memory response) {
    ...
    uint256 stipend = gasleft() - minGasReserve;
    (success, response) = to.delegatecall{ gas: stipend }(data);
    ...
}
```
If the minGasReserve is set to a high enough value the total required gas amount could be so high it would exceed the block size limit and never be able to get included in a block. This also applies to a transaction to set the minGasReserve back to a sane value resulting in an unusable proxy locking all the funds with it. The storage slot used for the minGasReserve can also accidentally (or intentionally by a malicious plugin or target contract) be overwritten with the same result. Additionally reserving a fixed amount of gas for post-processing the delegatecall serves no purpose. If we would rely on the normal 1/64th amount of gas reserved and it would not be sufficient for post-processing (which is limited to checking the success of the delegatecall and possibly reverting with the underlying reason) the transaction would revert due to insufficient gas. This behavior however is no different than when the minGasReserve is applied and the stipend for the delegatecall is reduced in which case the delegatecall would revert due to insufficient gas. In both situations the transaction reverts and the user needs to send the transaction again with an increased gas limit.

Envoys are given permissions on a target-by-target basis, with the assumption that they are not fully trusted with the assets of the proxy. When a proxy owner gives an envoy permissions on the SablierV2ProxyTarget, it is safe for them to assume that the user cannot steal their funds. This is because the only way to create a stream is to have a signed permit2 order from the owner, which allows the assets to be transferred to the proxy so the stream can be created.
```solidity
function _transferAndApprove(
    address sablierContract,
    IERC20 asset,
    uint160 amount,
    Permit2Params calldata permit2Params
)
    internal
{
    // Retrieve the proxy owner.
    address owner_ = owner;
    // Permit the proxy to spend funds from the proxy owner.
    permit2Params.permit2.permit({
        owner: owner_,
        permitSingle: permit2Params.permitSingle,
        signature: permit2Params.signature
    });
    // Transfer funds from the proxy owner to the proxy.
    permit2Params.permit2.transferFrom({ from: owner_, to: address(this), amount: amount, token: address(asset) });
    // Approve the Sablier contract to spend funds.
    _approve(sablierContract, asset, amount);
}
```
However, this _transferAndApprove() function allows the caller to input the Permit2Params, which includes the permit2 address that is used for the approval and transfer. This allows a malicious envoy to deploy their own dummy contract (with permit() and transferFrom() functions that pass but don't do anything), and then create a stream on behalf of the owner with this contract passed as the permit2 address. The result is that the createStream() function will call _transferAndApprove(), no checks will be performed in permit2, the asset will be approved for spending by Sablier, and the stream will be created. This stream could be uncancellable and send assets to themselves over a short time period, stealing all the funds in the proxy from the owner.

The _cancel() functions of the SablierV2LockupDynamic and SablierV2LockupLinear transfer the remaining funds for the sender and recipient in one call using the safeTransfer function for each:
```solidity
function _cancel(uint256 streamId) internal override onlySenderOrRecipient(streamId) {
    address recipient = _ownerOf(streamId);
    ...
    if (recipientAmount > 0) {
        ...
        stream.asset.safeTransfer({ to: recipient, value: recipientAmount });
    }
    if (senderAmount > 0) {
        stream.asset.safeTransfer({ to: sender, value: senderAmount });
    }
}
```
safeTransfer will revert when the underlying transfer fails in any way. As the recipient's address is determined by the ownership of the Sablier NFT, the recipient can front run the sender's cancel transaction by sending the NFT to an address known to revert by the underlying token's safeTransfer (e.g. an address on USDC's blocklist).  
While this may not directly beneﬁt the recipient, one could easily imagine a situation where a sender decides to cancel a stream, and a recipient is unhappy about it. In this case, they could call withdraw() to withdraw the full amount they are owed, and transfer the NFT to such an address, bricking the sender's funds.

PRBMath's pow() function takes in two signed integers, x and y, and returns x ** y.
```solidity
function pow(SD59x18 x, SD59x18 y) pure returns (SD59x18 result) {
    int256 xInt = x.unwrap();
    int256 yInt = y.unwrap();
    if (xInt == 0) {
        result = yInt == 0 ? UNIT : ZERO;
    } else {
        if (yInt == uUNIT) {
            result = x;
        } else {
            result = exp2(mul(log2(x), y));
        }
    }
}
```
A proper implementation of the pow() function should uphold the following invariant: If x >= y and a >= 0, then x ** a >= y ** a. This is a crucial invariant for the Sablier protocol, because the pow() function is used by SablierV2LockupDynamic.sol to compute total streamed amounts based on the current time. It is required for the protocol to function as expected that, as block.timestamp increases, the total streamed amount increases as well. Implications of this issue are addressed in C-01 of this report.  
• Proof of Concept
```solidity
function testPow() public {
    uint128 high = 505456470057136353;
    uint128 low = 505456461792312955;
    assert(high > low);
    SD59x18 exp = UD2x18.wrap(31414735).intoSD59x18();
    SD59x18 highPow = high.intoSD59x18().pow(exp);
    SD59x18 lowPow = low.intoSD59x18().pow(exp);
    assert(SD59x18.unwrap(highPow) < SD59x18.unwrap(lowPow));
}
```
• Root Cause Analysis  
In the exp2() function, bit masks are applied to multiply the result by root(2, 2**-i) for each position i with a value of 1. However, at Common.sol#L170, the value is incorrectly included as 0xFF00000000 instead of 0xFF000000. This bug was introduced in PR 77 on April 17th, 2022.

```solidity
function createVault(
    uint256 tokenIdOrAmount,
    address token,
    ...
) external returns (uint256 vaultId) {
    ...
    Vault memory vault = Vault({
        ...
    });

    // vault index should always be odd
    vaultIndex += 2;
    vaultId = vaultIndex;
    _vaults[vaultId] = vault;

    // give msg.sender vault token
    _mint(msg.sender, vaultId);

    emit NewVault(vaultId, msg.sender, token);

    // transfer the NFTs or ERC20s to the contract
