    assertEq(diamond.balanceOf(sender), 2);

    combineShorts({
        id1: Constants.SHORTSTARTINGID + 1,
        id2: Constants.SHORTSTARTINGID
    });

    assertEq(diamond.balanceOf(address(0xBEEF)), 0); // @audit-note 0xBEEF got its NFT burned!
