A negative funding rate retrieved from the consumer causes the interest rate to be calculated incorrectly. The FundingRateConsumer contract receives the funding rate from an API, which may be positive or negative, and stores it in the rates mapping as an int256. However, when the FundingRateOracle contract retrieves the rate from the consumer, it casts the result to uint256. This casting causes an underflow when the rate is negative, resulting in an extremely large value. Then, the InterestRateModel retrieves this rate in the InterestRateModel.getInterestRateAndUpdate() and calculates the current interest rate. Although the current rate value has a defined bounds, the result will not be as expected. Test that illustrates this case. To run the test: 1. Create new file (e.g. audit_fundingRateOracle.t.sol). 2. Put the code into the created file. 3. Run forge t --mt test_negativeFundingRateUnderflow -vvvv in the CLI.
```solidity
import {FundingRateOracle} from "contracts/FundingRateOracle.sol";
import {IFundingRateConsumer} from "interfaces/IFundingRateConsumer.sol";
import {IRepository} from "interfaces/IRepository.sol";
import {console2, Test} from "forge-std/Test.sol";

contract MockFundingRateConsumer {
    mapping(string => int256) public rates;

    function setRate(string memory ticker, int256 rate) external {
        rates[ticker] = rate;
    }
}

contract MockRepository {
    mapping(address => bool) public isManager;

    function setManager(address account, bool status) external {
        isManager[account] = status;
    }

    function isManagerRole(address account) external view returns (bool) {
        return isManager[account];
    }
}

contract PoC_FundingRateOracle is Test {
    FundingRateOracle public oracle;
    MockFundingRateConsumer public consumer;
    MockRepository public repository;
    address public constant MANAGER = address(0x1);
    address public constant TEST_ASSET = address(0x2);
    string public constant TEST_TICKER = "TEST";

    function setUp() public {
        consumer = new MockFundingRateConsumer();
        repository = new MockRepository();
        oracle = new FundingRateOracle(address(consumer), address(repository));
        repository.setManager(MANAGER, true);
    }

    // @audit This test demonstrates that a negative funding rate causes an underflow in the oracle contract.
    function test_negativeFundingRateUnderflow() external {
        vm.prank(MANAGER);
        oracle.addAsset(TEST_ASSET, TEST_TICKER);
        int256 expectedRate = -1000;
        consumer.setRate(TEST_TICKER, expectedRate);
        uint256 rate = oracle.getFundingRate(TEST_ASSET);
        assertNotEq(rate, uint256(-expectedRate));
    }
}
