By design, the GymVaultsBank contract is one of the main entries for interaction with users. In particular, it implements an incentive mechanism that rewards the staking of supported assets with the rewardToken token. One specific entry routine, i.e., deposit(), is designed to deposit the supported assets. While examining its logic, we observe there is a vulnerability that can be exploited by the malicious actor to claim the reward repeatedly.

To elaborate, we show below the related code snippet of the GymVaultsBank contract. At the beginning of the internal _deposit() routine (which is called inside the deposit() routine), the _claim() routine is invoked (line 433) to calculate and transfer the pending rewards to msg.sender. Additionally, we notice the _claim() routine is not in charge of user.rewardDebt update. That is to say, the user.rewardDebt should be updated outside the _claim() routine. After further analysis, we notice the user.rewardDebt is updated (line 456) only when the deposit amount is larger than 0 (line 436). With that, a malicious actor can claim the reward repeatedly by making the deposit amount 0. Given this, we suggest to update the user.rewardDebt regardless the actual deposit amount.

```solidity
function deposit(
    uint256 _pid,
    uint256 _wantAmt,
    uint256 _referrerId
) external payable nonReentrant onlyEmailVerified(msg.sender) {
    _deposit(_pid, _wantAmt);
    _updateLevelPoolQualification(msg.sender);
}

function _claim(uint256 _pid, address _user) private {
    PoolInfo memory pool = poolInfo[_pid];
    UserInfo storage user = userInfo[_pid][_user];
    uint256 pending = (user.shares * pool.accRewardPerShare) / (1e18) - (user.rewardDebt);
    if (pending > 0) {
        uint256 _distributedRewards = _distributeRewards(pending, rewardToken, _user);
        user.totalClaims += (pending - _distributedRewards);
        _safeRewardTransfer(rewardToken, _user, (pending - _distributedRewards));
        emit RewardPaid(rewardToken, _user, pending);
    }
}

function _deposit(uint256 _pid, uint256 _wantAmt) private {
    updatePool(_pid);
    PoolInfo memory pool = poolInfo[_pid];
    UserInfo storage user = userInfo[_pid][msg.sender];
    if (user.shares > 0) {
        _claim(_pid, msg.sender);
    }
    if (_wantAmt > 0) {
        if (msg.value == 0 && address(pool.want) != wbnbAddress) {
            // If want not WBNB
            pool.want.safeTransferFrom(address(msg.sender), address(this), _wantAmt);
            if (address(pool.want) == busdAddress) {
                user.dollarValue += (_wantAmt / 1e18);
            } else if (address(pool.want) == wbnbAddress) {
                user.dollarValue += ((_wantAmt * IGYMNETWORK(gymNetworkAddress).getBNBPrice()) / 1e18);
            }
        }
        pool.want.safeIncreaseAllowance(pool.strategy, _wantAmt);
        uint256 sharesAdded = IStrategy(poolInfo[_pid].strategy).deposit(msg.sender, _wantAmt);
        user.shares += sharesAdded;
        _updateInvestment(msg.sender);
        userInvestment[_pid][msg.sender] += _wantAmt;
    }
    user.rewardDebt = (user.shares * (pool.accRewardPerShare)) / (1e18);
    emit Deposit(msg.sender, _pid, _wantAmt);
}
```

The ERC721Base contract implements the standard ERC721 interfaces. Additionally, it implements the enumerability of all token IDs owned by the user.
In particular, mapping(address => uint256[]) internal _userTokens is designed to record all the token IDs held by the user and mapping(uint256 => uint256) internal _indexOfToken records the index of the token inside the user's token array. Meanwhile, the _addTokenTo() and _removeTokenFrom() routines are designed to manage the token IDs held by the user. While examining the related logic, we observe the current implementation should be improved.
To elaborate, we show below the related code snippet of the ERC721Base contract. Inside the _addTokenTo() routine, the statement of _userTokens[_to].push(_tokenId) (line 407) is executed to push the _tokenId to the _to's token array. Subsequently, the statement of _indexOfToken[_tokenId] = _userTokens[_to].length (line 408) is executed to record the index of the _tokenId inside the user's token array. However, it ignores the fact that the index of the array starts from 0.
```solidity
function _addTokenTo(address _to, uint256 _tokenId) internal {
    _tokenOwner[_tokenId] = _to;
    _userTokens[_to].push(_tokenId);
    _indexOfToken[_tokenId] = _userTokens[_to].length;
    _tokensCount = _tokensCount.add(1);
    _userPurchaseDate[_to] = block.timestamp;
}
```
Moreover, by design, the _removeTokenFrom() routine is used to remove the given _tokenId token from the given _from address. In order to meet the requirement, it needs to replace _tokenId with the last token ID inside the _from's token array and update the index of the last token ID. Eventually, the array's last element should be released via pop(). However, it comes to our attention that the current implementation is far from the design.
```solidity
function _removeTokenFrom(address _from, uint256 _tokenId) internal {
    uint256 tokenIndex = _indexOfToken[_tokenId];
    uint256 lastTokenIndex = _userTokens[_from].length.sub(1);
    uint256 lastTokenId = _indexOfToken[lastTokenIndex];
    _userTokens[_from][tokenIndex] = lastTokenId;
    _indexOfToken[lastTokenId] = tokenIndex;
    _userTokens[_from].pop();
    _tokenOwner[_tokenId] = address(0);
    _tokensCount = _tokensCount.sub(1);
    if (_userTokens[_from].length == 0) {
        delete _userTokens[_from];
    }
}
```

To improve the capital efficiency, the handle.fi protocol further supports the integration of external protocols for increased return. Accordingly, it maintains necessary accounting to keep track of the investment and gains about each external investment protocol. While examining the current accounting logic, we notice a specific function fails to properly maintain the accounting. To elaborate, we show below the full implementation of the ensureUpperBoundLimit() function, which checks the Treasury's collateral balance and total invested funds against maximum upper bound and withdraws from external protocol into Treasury if needed. Our analysis shows that it properly withdraws the funds from the external investment protocol and reduce the totalInvestments state. However, it fails to update the protocolInvestments state and it may corrupt the execution of a number of related functions, e.g., withdrawProtocolFunds().
```solidity
function ensureUpperBoundLimit(
    IPCTProtocolInterface pi,
    address collateralToken
) private {
    Pool storage pool = pools[collateralToken];
    uint256 totalInvested = pool.protocolInvestments[address(pi)];
    uint256 totalFunds = IERC20(collateralToken).balanceOf(address(treasury)).add(
        totalInvested
    );
    uint256 upperBound = handle.pctCollateralUpperBound();
    uint256 maxInvestmentAmount = totalFunds.mul(upperBound).div(1 ether);
    if (totalInvested <= maxInvestmentAmount) return;
    // Upper bound limit has been exceeded; withdraw from external protocol.
    uint256 diff = totalInvested.sub(maxInvestmentAmount);
    pi.withdraw(diff);
    pool.totalInvestments = pool.totalInvestments.sub(diff);
}
```

To facilitate the code organization and contain contract code size for deployment, the handle.fi protocol has a library contract named VaultLibrary. This library contract provides read-only functions to calculate vault data such as the collateral ratio, the equivalent ETH value of collateral/debt at the current exchange rates, weighted fees, etc. In the following, we examine a specific library function getNewMinimumRatio(). This function is designed to returns the new minimum vault ratio due to a collateral deposit or withdraw. It is mainly used for checking the collateralization ratio is valid before performing an operation. Our analysis shows the current implementation is only appropriate when there is a collateral deposit. However, it is flawed when there is a collateral withdraw.
```solidity
function getNewMinimumRatio(
    address account,
    address fxToken,
    address collateralToken,
    uint256 collateralAmount,
    uint256 collateralQuote,
    bool isDeposit
) public view override returns (uint256 ratio, uint256 newCollateralAsEther) {
    uint256 currentMinRatio = getMinimumRatio(account, fxToken);
    uint256 vaultCollateral = getTotalCollateralBalanceAsEth(account, fxToken);
    // Calculate new vault collateral from deposit amount.
    newCollateralAsEther = isDeposit
        ? vaultCollateral.add(
            collateralQuote.mul(collateralAmount).div(
                getTokenUnit(collateralToken)
            )
        )
        : vaultCollateral.sub(
            collateralQuote.mul(collateralAmount).div(
                getTokenUnit(collateralToken)
            )
        );
    uint256 depositCollateralMintCR = handle.getCollateralDetails(collateralToken).mintCR;
    if (currentMinRatio == 0) {
        ratio = depositCollateralMintCR.mul(1 ether).div(100);
    } else {
        /* Ratio for the current share of minimum collateral ratio due to the deposit change (i.e. if vault holds $50 and the new deposit is $50, this value is 50% expressed as 0.5 ether). */
        uint256 oldCollateralMintRatio = vaultCollateral.mul(1 ether).div(newCollateralAsEther);
        // Calculate new minimum ratio using the CR ratio above.
        ratio = currentMinRatio
            .mul(oldCollateralMintRatio)
            .div(1 ether)
            .add(
                uint256(1 ether)
                .sub(oldCollateralMintRatio)
                .mul(depositCollateralMintCR)
                .div(1 ether)
            );
    }
}
```
Specifically, the internal variable oldCollateralMintRatio is used to represent the ratio for the current share of minimum collateral ratio due to the deposit change. In a collateral deposit scenario, this variable is no larger than 1 eth, which yields the proper ratio. However, in a collateral withdraw scenario, this variable is no smaller than 1 eth, which can easily result in reverting the execution due to the SafeMath operation on uint256(1 ether).sub(oldCollateralMintRatio) (lines 565-566).

HBTC Chain is developed on top of Cosmos-SDK[7], a popular modular framework for building application-specific blockchains. Note that Cosmos-SDK enables rapid development of SDK-based blockchains out of composable modules. HBTC Chain leverages some existing modules (with its own customization) and further develops unique ones for the purpose of digital asset custody and clearing. Speciﬁcally, cu provides a custody unit for asset management, token enlists available tokens for trading or custody, mapping supports cross-chain asset mapping, keygen provides dynamic key generation services for cross-chain assets, and hrc20 enables ERC20-like token issuance and transfer primitives on HBTC Chain etc. The modular Cosmos-SDK framework allows various modules to generally handle a subset of the state and, as such, these modules need to define the related subset of the genesis file as well as methods to initialize, verify, and export it. We stress that these states are essential to the blockchain's genesis state import and export and are therefore required for seamless upgrades. In the current HBTC Chain codebase, several modules do not have thorough genesis-related states properly exported or imported. Consequently, they could lead to broken upgrades. Using the custodianunit (a.k.a., cu) module as an example, we show below the implementation of current InitGenesis and ExportGenesis routines. As the names indicate, they are executed whenever an import or export of the state is made. The ExportGenesis routine exported both params and cus, but the InitGenesis routine only imported params, not cus. In other words, all created cus in a previous run may be lost for a resumed run of HBTC Chain after upgrade.
```go
// InitGenesis - Init store state from genesis data
// CONTRACT: old coins from the FeeCollectionKeeper need to be transferred through
// a genesis port script to the new fee collector
func InitGenesis(ctx sdk.Context, ak CUKeeper, data GenesisState) {
    ak.SetParams(ctx, data.Params)
}

// ExportGenesis returns a GenesisState for a given context and keeper
func ExportGenesis(ctx sdk.Context, ck CUKeeper) GenesisState {
    params := ck.GetParams(ctx)
    cus := ck.GetAllCUs(ctx)
    return NewGenesisState(params, cus)
}
```
Incomplete, without the validation of saved cus in the genesis state.
```go
// ValidateGenesis performs basic validation of auth genesis data returning
// error for any failed validation criteria.
func ValidateGenesis(data GenesisState) error {
    if data.Params.TxSigLimit == 0 {
        return fmt.Errorf("invalid signature limit: %d", data.Params.TxSigLimit)
    }
    if data.Params.SigVerifyCostED25519 == 0 {
        return fmt.Errorf("invalid ED25519 signature verification cost: %d", data.Params.SigVerifyCostED25519)
    }
    if data.Params.SigVerifyCostSecp256k1 == 0 {
        return fmt.Errorf("invalid SECK256k1 signature verification cost: %d", data.Params.SigVerifyCostSecp256k1)
    }
    if data.Params.MaxMemoCharacters == 0 {
        return fmt.Errorf("invalid max memo characters: %d", data.Params.MaxMemoCharacters)
    }
    if data.Params.TxSizeCostPerByte == 0 {
        return fmt.Errorf("invalid tx size cost per byte: %d", data.Params.TxSizeCostPerByte)
    }
    return nil
}
