function _withdrawSome(uint256 _amount) internal returns (uint256) {
    _amount = Math.min(_amount, IGenericMarginPool(pool).nav());
    // dont withdraw dust
    if (_amount < withdrawalThreshold) {
        return 0;
    }
    return IGenericMarginPool(pool).withdraw(_amount);
}
