            transferNftInternal(address(this), _order.pledger, _order.collection, _order.tokenId, _order.nftType);
            _order.isWithdraw = true;
            emit WithDraw(_order.collection, _order.tokenId, orderId, _order.pledger, msg.sender);
        }
    }
}
