ITOFT(collateralAddress).unwrap(address(this), collateralAmountIn);
//redeem from sDai
uint256 obtainedDai = ISavingsDai(sDaiAddress).redeem(
    ISavingsDai(sDaiAddress).convertToShares(collateralAmountIn), address(this), address(this)
