    if (ownerOf(_tokenId) == address(0)) revert NonExistentToken();
    // If tokenId < 10000, it's a FrankenPunk, so 100/100 = a multiplier of 1
    uint multiplier = _tokenId < 10_000 ? PERCENT : monsterMultiplier;
