        address,
        address,
        uint256,
        uint256,
        bytes memory
    ) public virtual override returns (bytes4) {
        if (!reentrant) {
            reentrant = true;
            uncuts_contract.buy(address(this), 1, 1, type(uint256).max);
        }
        return this.onERC1155Received.selector;
    }
}
