    for (uint i = 0; i < 366; i++) {
        contribute(100e18);
        awardDraw(1);
        mockTwab(address(this), msg.sender, 0);
    }
    address otherVault = makeAddr("otherVault");
    vm.prank(otherVault);
    prizePool.contributePrizeTokens(otherVault, 0);
    uint256 prize = claimPrize(msg.sender, 0, 0);
}
